begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into auth.users(id,email) values ('00000000-0000-0000-0000-00000000a501','prefs-a@example.com'),('00000000-0000-0000-0000-00000000b501','prefs-b@example.com');
insert into friendships(requester_id,addressee_id,status) values ('00000000-0000-0000-0000-00000000a501','00000000-0000-0000-0000-00000000b501','accepted');
select ok((select relrowsecurity from pg_class where oid='public.account_preferences'::regclass),'preferences enforce RLS');
select ok(not has_table_privilege('anon','public.account_preferences','SELECT'),'anonymous cannot read');
select ok(not has_table_privilege('authenticated','public.account_preferences','INSERT'),'no direct insertion');
select ok(not has_table_privilege('authenticated','public.account_preferences','UPDATE'),'no direct update');
select ok(not has_table_privilege('authenticated','public.account_preferences','DELETE'),'no direct deletion');
select ok(not has_function_privilege('anon','public.set_account_preference(text,jsonb,bigint)','EXECUTE'),'no anonymous writes');
select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='public.set_account_preference(text,jsonb,bigint)'::regprocedure),'definer path pinned');
select ok(public.valid_account_preference('pet','null'),'nullable pet');
select ok(public.valid_account_preference('name_cat','"My cat"'),'normalized name');
select ok(not public.valid_account_preference('name_cat','" bad "'),'no unnormalized name');
select ok(not public.valid_account_preference('name_cat',to_jsonb(E'bad\nname'::text)),'no name control characters');
select ok(not public.valid_account_preference('name_cat',to_jsonb(repeat('🐱',25))),'unicode name cap');
select ok(public.valid_account_preference('name_cat',to_jsonb(repeat('🐱',24))),'unicode names use code points');
select ok(not public.valid_account_preference('presets','[{"name":"a","focus":25,"break":5,"unexpected":true}]'),'all preset fields required');
select ok(not public.valid_account_preference('presets','[{"name":"a","mode":"flow","focus":7,"break":5}]'),'focus step enforced');
select ok(not public.valid_account_preference('presets','[{"name":"a","mode":"flow","focus":25,"break":0}]'),'break bounds enforced');
select ok(not public.valid_account_preference('presets','[{"name":"a","mode":"flow","focus":25,"break":5},{"name":"A","mode":"flow","focus":25,"break":5}]'),'case-insensitive duplicate names');
select ok(not public.valid_account_preference('presets',(select jsonb_agg(jsonb_build_object('name',n::text,'mode','flow','focus',25,'break',5)) from generate_series(1,6)n)),'five favorite cap');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000a501',true);
select throws_ok($$select set_account_preference('is_premium','true',null)$$,'22023','Invalid preference','no privileged profile settings');
select throws_ok($$select set_account_preference('quiet_focus','"yes"',null)$$,'22023','Invalid preference','boolean validation');
select throws_ok($$select set_account_preference('daily_goal','61',null)$$,'22023','Invalid preference','target allowlist');
select throws_ok($$select set_account_preference('pet','"fox"',null)$$,'22023','Invalid preference','pet allowlist');
select throws_ok($$select set_account_preference('pet','"cat"',0)$$,'22023','Invalid preference','revision validation');
select lives_ok($$select set_account_preference('pet','"cat"',null)$$,'creates own pet');
select lives_ok($$select set_account_preference('name_cat','"Nori"',null)$$,'creates own name');
select lives_ok($$select set_account_preference('presets','[{"name":"Deep","mode":"pomodoro","focus":50,"break":10}]',null)$$,'creates favorites');
select lives_ok($$select set_account_preference('daily_goal','90',null)$$,'creates target');
select lives_ok($$select set_account_preference('quiet_focus','true',null)$$,'creates quiet mode');
select throws_ok($$select set_account_preference('pet','"dog"',null)$$,'PT409','Preference changed elsewhere','create cannot overwrite');
select lives_ok($$select set_account_preference('pet',null,1)$$,'RPC null clears pet while retaining row');
select is((select value from account_preferences where key='pet'),'null'::jsonb,'cleared pet retained');
select is((select version from account_preferences where key='pet'),2::bigint,'clear advances revision');
select throws_ok($$select set_account_preference('pet','"dog"',1)$$,'PT409','Preference changed elsewhere','stale write cannot revive reset');
select lives_ok($$select set_account_preference('presets','[]',1)$$,'empty favorites retained');
select is((select version from account_preferences where key='daily_goal'),1::bigint,'unrelated revision unchanged');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-00000000b501',true);
select is((select count(*) from account_preferences),0::bigint,'accepted friend cannot read preferences');
select throws_ok($$select set_account_preference('pet','"dog"',2)$$,'PT409','Preference changed elsewhere','friend cannot change owner row');
select lives_ok($$select set_account_preference('pet','"rabbit"',null)$$,'friend has independent preferences');
select is((select count(*) from account_preferences),1::bigint,'only own row visible');
reset role;
delete from auth.users where id='00000000-0000-0000-0000-00000000a501';
select is((select count(*) from account_preferences where user_id='00000000-0000-0000-0000-00000000a501'),0::bigint,'account deletion cascades preferences');
select * from finish();
rollback;
